mapper.select:
SELECT r.*,
       (SELECT COUNT(*) FROM base_downtime d WHERE d.reason_id = r.reason_id) AS use_count
FROM base_downtime_reason r


        AND r.reason_type = #{reasonType}


        AND r.use_yn = #{useYn}


ORDER BY r.sort_order ASC, r.reason_code ASC

SELECT d.*, e.equip_code, e.equip_name, r.reason_code, r.reason_name, r.reason_type, TIMESTAMPDIFF(MINUTE, d.start_dt, IFNULL(d.end_dt, NOW())) AS duration_min FROM base_downtime d JOIN base_equipment e ON e.equip_id = d.equip_id JOIN base_downtime_reason r ON r.reason_id = d.reason_id
AND IFNULL(d.end_dt, NOW()) >= #{from}
AND d.start_dt < #{to}
AND d.equip_id = #{equipId}
AND r.reason_type = #{reasonType}
AND (r.reason_name LIKE CONCAT('%', #{keyword}, '%') OR d.memo LIKE CONCAT('%', #{keyword}, '%') OR d.reg_user_name LIKE CONCAT('%', #{keyword}, '%') OR d.reg_user_id LIKE CONCAT('%', #{keyword}, '%') OR d.upd_user_name LIKE CONCAT('%', #{keyword}, '%') OR d.upd_user_id LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY d.start_dt DESC, e.equip_code ASC

SELECT COUNT(*)
FROM base_downtime
WHERE equip_id = #{equipId}
  AND start_dt < IFNULL(#{endDt}, '9999-12-31')
  AND IFNULL(end_dt, '9999-12-31') > #{startDt}

    AND downtime_id != #{excludeId}
